import { defineSlot } from '../Slot';

/**
 * A project's detail page. Features fill this region with panels about one project (its invoices,
 * their total, an add-invoice form). The detail route renders it with the project id as context;
 * the page never lists what goes in it, so each panel is a new *.slot.tsx file.
 */
export const ProjectDetail = defineSlot<{ projectId: number }>('project.detail');

import { Outlet, createRootRouteWithContext } from '@tanstack/react-router';
import type { QueryClient } from '@tanstack/react-query';
import { AppNav } from '../slots/defs/appNav';

// The whole shell. It renders the nav region and the matched route — it does NOT know what pages
// exist (they contribute to app.nav and appear under routes/), and it holds no state (what is open
// or filtered is in the URL). Nothing about a new feature belongs in this file. Do not edit it.
export const Route = createRootRouteWithContext<{ queryClient: QueryClient }>()({
  // Search params are an OPEN namespace, declared once here and inherited by every route: a feature
  // claims a key just by reading/writing it (url/useSearchParam), so adding a filter or a selection
  // is never an edit to a schema.
  validateSearch: (search: Record<string, unknown>) => search,
  component: AppShell,
});

function AppShell() {
  return (
    <div data-testid="app-root">
      <nav data-testid="app-nav">
        <AppNav.Slot />
      </nav>
      <main data-testid="app-home">
        <Outlet />
      </main>
    </div>
  );
}

-- An invoice now carries two dates: when it was issued (went out) and when it is due. Both are plain
-- calendar dates (DATE, no time-of-day), so the UI shows a bare YYYY-MM-DD. New and existing rows get
-- CURRENT_DATE as a safe default; the test seed supplies explicit dates, and CreateInvoice sets its
-- own, so the default only guards rows raised before this column existed.
ALTER TABLE invoices ADD COLUMN issued_date DATE NOT NULL DEFAULT CURRENT_DATE;
ALTER TABLE invoices ADD COLUMN due_date DATE NOT NULL DEFAULT CURRENT_DATE;

